<?php
require_once __DIR__.'/../config.php';require_admin();$pageTitle='Manage users';
if(is_post()){verify_csrf();$id=valid_id($_POST['id']??0);$action=$_POST['action']??'';if($id===(int)current_user()['id'])set_flash('error','You cannot change your own account status here.');else{$stmt=$pdo->prepare("SELECT id,role FROM users WHERE id=?");$stmt->execute([$id]);$u=$stmt->fetch();if(!$u)set_flash('error','User not found.');elseif($u['role']==='admin')set_flash('error','Admin accounts cannot be blocked from this screen.');elseif($action==='toggle'){$pdo->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=?")->execute([$id]);set_flash('success','User status updated.');}elseif($action==='delete'){$pdo->prepare("DELETE FROM users WHERE id=?")->execute([$id]);set_flash('success','User account deleted.');}}redirect('users.php');}
$search=trim((string)($_GET['q']??''));$sql='SELECT u.id,u.name,u.email,u.role,u.status,u.created_at,(SELECT COUNT(*) FROM resources r WHERE r.uploader_id=u.id) uploads FROM users u';$args=[];if($search!==''){$sql.=' WHERE u.name LIKE ? OR u.email LIKE ?';$like='%'.$search.'%';$args=[$like,$like];}$sql.=' ORDER BY u.created_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($args);$users=$stmt->fetchAll();require __DIR__.'/../includes/admin_header.php';?>
<form class="search-form mb-2"><input type="search" name="q" value="<?= e($search) ?>" placeholder="Search by name or email"><button class="btn btn-primary">Search</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Uploads</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><div class="small-muted"><?= e($u['email']) ?></div></td><td><?= e(ucfirst($u['role'])) ?></td><td><?= badge($u['status']) ?></td><td><?= (int)$u['uploads'] ?></td><td><?= e(date('M j, Y',strtotime($u['created_at']))) ?></td><td><?php if($u['role']!=='admin' && (int)$u['id']!==(int)current_user()['id']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-outline btn-small"><?= $u['status']==='active'?'Block':'Unblock' ?></button></form> <form method="post" data-confirm="Delete this user account?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small">Delete</button></form><?php else: ?><span class="small-muted">Protected</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php require __DIR__.'/../includes/admin_footer.php';?>
